class StockPage extends StatefulWidget{final bool admin;const StockPage({super.key,required this.admin});@override State<StockPage>createState()=>_StockPageState();}
class _StockPageState extends State<StockPage>{late Future<List<Map<String,dynamic>>>f;List<Map<String,dynamic>>agents=[];List<Map<String,dynamic>>products=[];@override void initState(){super.initState();f=load();}Future<List<Map<String,dynamic>>>load()async{if(widget.admin){final p=await db.from('products').select('id,name,selling_price,central_stock,active').order('name');final a=await db.from('profiles').select('id,full_name').eq('role','agent').order('full_name');products=List<Map<String,dynamic>>.from(p);agents=List<Map<String,dynamic>>.from(a);return products;}final x=await db.from('agent_stock').select('quantity,products(name,selling_price)').eq('agent_id',db.auth.currentUser!.id);return List<Map<String,dynamic>>.from(x);}
 Future<void>editProduct(Map<String,dynamic>p)async{final price=TextEditingController(text:'${p['selling_price']}'),stock=TextEditingController(text:'${p['central_stock']}');await showDialog(context:context,builder:(_)=>AlertDialog(title:Text('${p['name']}'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:price,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Selling price')),TextField(controller:stock,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Central stock'))]),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('CANCEL')),FilledButton(onPressed:()async{final pr=double.tryParse(price.text),st=int.tryParse(stock.text);if(pr==null||st==null||st<0)return;await db.from('products').update({'selling_price':pr,'central_stock':st,'updated_at':DateTime.now().toIso8601String()}).eq('id',p['id']);if(mounted){Navigator.pop(context);setState(()=>f=load());}},child:const Text('SAVE'))]));}
 Future<void>assignStock()async{String?aid,pid;final qty=TextEditingController();await showDialog(context:context,builder:(_)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:const Text('Set Agent Stock'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(items:[for(final a in agents)DropdownMenuItem(value:'${a['id']}',child:Text('${a['full_name']}'))],onChanged:(v)=>set(()=>aid=v),decoration:const InputDecoration(labelText:'Agent')),DropdownButtonFormField<String>(items:[for(final p in products)DropdownMenuItem(value:'${p['id']}',child:Text('${p['name']}'))],onChanged:(v)=>set(()=>pid=v),decoration:const InputDecoration(labelText:'Product')),TextField(controller:qty,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Quantity in care'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('CANCEL')),FilledButton(onPressed:()async{final n=int.tryParse(qty.text);if(aid==null||pid==null||n==null||n<0)return;await db.rpc('tz_set_agent_stock',params:{'p_agent':aid,'p_product':pid,'p_quantity':n});if(mounted){Navigator.pop(c);ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Agent stock updated.')));}},child:const Text('SAVE'))]));}
 @override Widget build(BuildContext c)=>FutureBuilder(future:f,builder:(_,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final r=s.data!;return ListView(padding:const EdgeInsets.all(14),children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(widget.admin?'Central Stock':'My Stock',style:const TextStyle(fontSize:26,fontWeight:FontWeight.w900,color:navy)),if(widget.admin)Wrap(children:[IconButton(onPressed:assignStock,icon:const Icon(Icons.person_add_alt_1)),])]),for(final p in r)Card(child:ListTile(title:Text(widget.admin?'${p['name']}':'${p['products']?['name']??'Product'}'),subtitle:Text(widget.admin?'Selling price: ₦${p['selling_price']}':'Quantity in care: ${p['quantity']}'),trailing:widget.admin?IconButton(onPressed:()=>editProduct(p),icon:const Icon(Icons.edit)):Text('${p['quantity']}',style:const TextStyle(fontSize:20,fontWeight:FontWeight.w900))))]);});}

String receiptText(Map<String,dynamic>o,List<Map<String,dynamic>>items,String receipt){final b=StringBuffer();b.writeln('TEMZ STORE');b.writeln('QUALITY • TRUST • VALUE');b.writeln('09012533620');b.writeln();b.writeln('RECEIPT: $receipt');b.writeln('TZ ORDER: ${o['order_number']}');b.writeln('DATE: ${DateTime.now().toString().substring(0,16)}');b.writeln();b.writeln('CUSTOMER: ${o['customer_name']}');b.writeln('PHONE: ${o['customer_phone']}');b.writeln('ADDRESS: ${o['delivery_address']}, ${o['city']}, ${o['state']}');b.writeln();for(final i in items)b.writeln('${i['products']?['name']??'Product'}  x${i['quantity']}');b.writeln();b.writeln('TOTAL PAID: ₦${o['total_amount']??0}');b.writeln('PAYMENT METHOD: ${o['payment_method']??'Not recorded'}');b.writeln();b.writeln('**********************');b.writeln('          PAID');b.writeln('**********************');return b.toString();}
class ReceiptsPage extends StatefulWidget{const ReceiptsPage({super.key});@override State<ReceiptsPage>createState()=>_ReceiptsPageState();}
class _ReceiptsPageState extends State<ReceiptsPage>{late Future<List<Map<String,dynamic>>>f;@override void initState(){super.initState();f=load();}Future<List<Map<String,dynamic>>>load()async{final x=await db.from('receipts').select('id,receipt_number,generated_at,order_id,orders(order_number,customer_name,total_amount,payment_method,customer_phone,delivery_address,city,state)').order('generated_at',ascending:false);return List<Map<String,dynamic>>.from(x);}@override Widget build(BuildContext c)=>FutureBuilder(future:f,builder:(_,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final r=s.data!;return ListView(padding:const EdgeInsets.all(14),children:[const Text('Customer Receipts',style:TextStyle(fontSize:26,fontWeight:FontWeight.w900,color:navy)),for(final x in r)Card(child:ListTile(title:Text('${x['receipt_number']}'),subtitle:Text('${x['orders']?['order_number']} • ${x['orders']?['customer_name']}'),trailing:IconButton(icon:const Icon(Icons.share),onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>ReceiptPage(order:Map<String,dynamic>.from(x['orders']),items:const[],receiptNumber:'${x['receipt_number']}'))))) ]);});}
class ReceiptPage extends StatelessWidget{final Map<String,dynamic>order;final List<Map<String,dynamic>>items;final String?receiptNumber;const ReceiptPage({super.key,required this.order,required this.items,this.receiptNumber});@override Widget build(BuildContext c){final r=receiptNumber??'RCP-${DateTime.now().millisecondsSinceEpoch}';final text=receiptText(order,items,r);return Scaffold(appBar:AppBar(title:const Text('Customer Receipt'),actions:[IconButton(onPressed:()=>SharePlus.instance.share(ShareParams(text:text,subject:'Temz Store Receipt ${order['order_number']}')),icon:const Icon(Icons.share))]),body:ListView(padding:const EdgeInsets.all(20),children:[const Logo(size:110),const Center(child:Text('TEMZ STORE',style:TextStyle(fontSize:23,fontWeight:FontWeight.w900,color:navy))),const Center(child:Text('09012533620')),const SizedBox(height:18),Card(child:Padding(padding:const EdgeInsets.all(18),child:Text(text,style:const TextStyle(fontSize:15,height:1.45)))),const SizedBox(height:12),const Center(child:Text('PAID',style:TextStyle(fontSize:34,fontWeight:FontWeight.w900,color:green)))]);}}

