class _AdminsPageState extends State<AdminsPage>{late Future<List<Map<String,dynamic>>>f;@override void initState(){super.initState();f=load();}Future<List<Map<String,dynamic>>>load()async{final x=await db.from('profiles').select('id,full_name,email,role,available').order('role').order('full_name');return List<Map<String,dynamic>>.from(x);}Future<void>setRole(String id,bool v)async{try{await db.rpc('tz_set_admin_role',params:{'p_user':id,'p_make_admin':v});setState(()=>f=load());}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}@override Widget build(BuildContext c)=>FutureBuilder(future:f,builder:(_,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final r=s.data!;return ListView(padding:const EdgeInsets.all(14),children:[const Text('Admin Management',style:TextStyle(fontSize:26,fontWeight:FontWeight.w900,color:navy)),const Text('Promote an existing TZ account to admin or revoke admin access.'),for(final x in r)Card(child:ListTile(title:Text('${x['full_name']??''}'),subtitle:Text('${x['email']} • ${x['role']}'),trailing:x['role']=='admin'?OutlinedButton(onPressed:'${x['id']}'==db.auth.currentUser?.id?null:()=>setRole('${x['id']}',false),child:const Text('REMOVE ADMIN')):FilledButton(onPressed:()=>setRole('${x['id']}',true),child:const Text('MAKE ADMIN'))))]);});}
